{
  "name": "Short-Form Bookmark Master",
  "description": "A mobile-optimized web application to save and manage Reels, TikTok, and YouTube Shorts with automatic thumbnail extraction and Google Sheets integration.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Category = '전체' | '프리다이빙' | '여행' | '우정릴스' | '인증샷' | '귀여움' | '캠핑팁';

export interface Bookmark {
  id: string;
  date: string;
  url: string;
  thumbnail: string;
  memo: string;
  category: Category;
}

export interface GASResponse {
  success: boolean;
  message?: string;
  data?: any;
}

import { Category } from './types';

export const CATEGORIES: Category[] = [
  '전체',
  '프리다이빙',
  '여행',
  '우정릴스',
  '인증샷',
  '귀여움',
  '캠핑팁'
];

export const CATEGORY_COLORS: Record<string, string> = {
  '전체': 'bg-slate-100 text-slate-700 border-slate-200',
  '프리다이빙': 'bg-blue-100 text-blue-700 border-blue-200',
  '여행': 'bg-emerald-100 text-emerald-700 border-emerald-200',
  '우정릴스': 'bg-purple-100 text-purple-700 border-purple-200',
  '인증샷': 'bg-orange-100 text-orange-700 border-orange-200',
  '귀여움': 'bg-pink-100 text-pink-700 border-pink-200',
  '캠핑팁': 'bg-amber-100 text-amber-700 border-amber-200'
};

import React, { useState, useEffect, useCallback } from 'react';
import { Plus, Search, Filter, PlayCircle, Loader2 } from 'lucide-react';
import { Bookmark, Category } from './types';
import { CATEGORIES } from './constants';
import Header from './components/Header';
import FilterBar from './components/FilterBar';
import BookmarkCard from './components/BookmarkCard';
import AddBookmarkForm from './components/AddBookmarkForm';

const App: React.FC = () => {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [filteredBookmarks, setFilteredBookmarks] = useState<Bookmark[]>([]);
  const [activeCategory, setActiveCategory] = useState<Category>('전체');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Fetch bookmarks from GAS (Mocking initial load for now)
  const fetchBookmarks = useCallback(async () => {
    setIsLoading(true);
    try {
      // In real deployment: google.script.run.withSuccessHandler((data) => setBookmarks(data)).getEntries();
      // Simulating network delay
      await new Promise(resolve => setTimeout(resolve, 800));

      const savedData = localStorage.getItem('bookmarks');
      if (savedData) {
        setBookmarks(JSON.parse(savedData));
      } else {
        // Initial sample data
        const sample: Bookmark[] = [
          {
            id: '1',
            date: new Date().toISOString(),
            url: 'https://www.youtube.com/shorts/sample1',
            thumbnail: 'https://picsum.photos/seed/reels/400/600',
            memo: '제주도 바다속 풍경!',
            category: '프리다이빙'
          },
          {
            id: '2',
            date: new Date().toISOString(),
            url: 'https://www.instagram.com/reels/sample2',
            thumbnail: 'https://picsum.photos/seed/travel/400/600',
            memo: '친구들이랑 인생샷 명소',
            category: '인증샷'
          }
        ];
        setBookmarks(sample);
        localStorage.setItem('bookmarks', JSON.stringify(sample));
      }
    } catch (error) {
      console.error('Failed to fetch bookmarks:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchBookmarks();
  }, [fetchBookmarks]);

  // Filtering logic
  useEffect(() => {
    let result = bookmarks;
    if (activeCategory !== '전체') {
      result = result.filter(b => b.category === activeCategory);
    }
    if (searchQuery) {
      result = result.filter(b => 
        b.memo.toLowerCase().includes(searchQuery.toLowerCase()) ||
        b.category.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }
    setFilteredBookmarks(result.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  }, [bookmarks, activeCategory, searchQuery]);

  const handleAddBookmark = (newBookmark: Bookmark) => {
    const updated = [newBookmark, ...bookmarks];
    setBookmarks(updated);
    localStorage.setItem('bookmarks', JSON.stringify(updated));
    // In real deployment: google.script.run.addEntry(newBookmark);
  };

  const handleDeleteBookmark = (id: string) => {
    const updated = bookmarks.filter(b => b.id !== id);
    setBookmarks(updated);
    localStorage.setItem('bookmarks', JSON.stringify(updated));
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <Header />

      <main className="max-w-md mx-auto px-4 pt-4">
        {/* Search Bar */}
        <div className="relative mb-6">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-slate-400" />
          </div>
          <input
            type="text"
            className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-2xl bg-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all shadow-sm text-sm"
            placeholder="동영상 검색 또는 메모 검색..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        {/* Categories */}
        <FilterBar 
          activeCategory={activeCategory} 
          onCategoryChange={setActiveCategory} 
        />

        {/* Content */}
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 opacity-50">
            <Loader2 className="h-8 w-8 animate-spin text-indigo-600 mb-2" />
            <p className="text-sm font-medium">데이터 불러오는 중...</p>
          </div>
        ) : filteredBookmarks.length > 0 ? (
          <div className="grid grid-cols-2 gap-4 mt-6">
            {filteredBookmarks.map((bookmark) => (
              <BookmarkCard 
                key={bookmark.id} 
                bookmark={bookmark} 
                onDelete={handleDeleteBookmark}
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-20">
            <div className="bg-slate-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
              <PlayCircle className="h-8 w-8 text-slate-400" />
            </div>
            <p className="text-slate-500 text-sm">저장된 콘텐츠가 없습니다.</p>
            {searchQuery && (
              <button 
                onClick={() => setSearchQuery('')}
                className="mt-2 text-indigo-600 text-xs font-semibold"
              >
                검색어 초기화
              </button>
            )}
          </div>
        )}
      </main>

      {/* Floating Action Button */}
      <button
        onClick={() => setIsFormOpen(true)}
        className="fixed bottom-6 right-6 w-14 h-14 bg-indigo-600 text-white rounded-full shadow-lg flex items-center justify-center hover:bg-indigo-700 active:scale-95 transition-all z-40"
      >
        <Plus className="h-6 w-6" />
      </button>

      {/* Add Modal */}
      {isFormOpen && (
        <AddBookmarkForm 
          onClose={() => setIsFormOpen(false)} 
          onSubmit={handleAddBookmark}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { BookmarkCheck } from 'lucide-react';

const Header: React.FC = () => {
  return (
    <header className="sticky top-0 bg-white/80 backdrop-blur-md border-b border-slate-100 z-30">
      <div className="max-w-md mx-auto px-4 h-16 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="bg-indigo-600 p-2 rounded-xl">
            <BookmarkCheck className="h-5 w-5 text-white" />
          </div>
          <h1 className="text-lg font-bold bg-gradient-to-r from-indigo-600 to-indigo-400 bg-clip-text text-transparent">
            Shorts Favs
          </h1>
        </div>
        <div className="flex gap-2">
           <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center">
