export default FilterBar;

import React from 'react';
import { ExternalLink, Trash2, Calendar } from 'lucide-react';
import { Bookmark } from '../types';
import { CATEGORY_COLORS } from '../constants';

interface BookmarkCardProps {
  bookmark: Bookmark;
  onDelete: (id: string) => void;
}

const BookmarkCard: React.FC<BookmarkCardProps> = ({ bookmark, onDelete }) => {
  const formatDate = (dateStr: string) => {
    const d = new Date(dateStr);
    return `${d.getMonth() + 1}/${d.getDate()}`;
  };

  return (
    <div className="group bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-all border border-slate-100 flex flex-col h-full">
      <div className="relative aspect-[3/4] overflow-hidden">
        <img 
          src={bookmark.thumbnail} 
          alt="Thumbnail" 
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
        />
        <div className="absolute top-2 left-2">
          <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold border ${CATEGORY_COLORS[bookmark.category]}`}>
            {bookmark.category}
          </span>
        </div>
        <a 
          href={bookmark.url} 
          target="_blank" 
          rel="noopener noreferrer"
          className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/30 backdrop-blur-[2px]"
        >
          <div className="bg-white/90 p-3 rounded-full shadow-lg">
            <ExternalLink className="h-5 w-5 text-indigo-600" />
          </div>
        </a>
      </div>

      <div className="p-3 flex flex-col flex-grow">
        <p className="text-sm font-medium text-slate-800 line-clamp-2 mb-2 min-h-[40px]">
          {bookmark.memo || '메모가 없습니다.'}
        </p>

        <div className="flex items-center justify-between mt-auto">
          <div className="flex items-center gap-1 text-[10px] text-slate-400 font-medium">
            <Calendar className="h-3 w-3" />
            {formatDate(bookmark.date)}
          </div>
          <button 
            onClick={() => {
              if (confirm('삭제하시겠습니까?')) onDelete(bookmark.id);
            }}
            className="p-1.5 text-slate-300 hover:text-red-500 transition-colors"
          >
            <Trash2 className="h-3.5 w-3.5" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default BookmarkCard;

import React, { useState } from 'react';
import { X, Link as LinkIcon, Type, Image, Upload, Loader2, Sparkles } from 'lucide-react';
import { Bookmark, Category } from '../types';
import { CATEGORIES } from '../constants';
import { GoogleGenAI } from "@google/genai";

interface AddBookmarkFormProps {
  onClose: () => void;
  onSubmit: (bookmark: Bookmark) => void;
}

const AddBookmarkForm: React.FC<AddBookmarkFormProps> = ({ onClose, onSubmit }) => {
  const [url, setUrl] = useState('');
  const [memo, setMemo] = useState('');
  const [category, setCategory] = useState<Category>('전체');
  const [thumbnail, setThumbnail] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setThumbnail(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAutoThumbnail = async () => {
    if (!url) return alert('URL을 먼저 입력해주세요.');
    setIsProcessing(true);

    try {
      // Logic: Use Gemini to "simulate" or "suggest" a summary/category/thumbnail if we don't have a real scraper
      // In real GAS, we would use UrlFetchApp
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `I have this short-form video URL: ${url}. 
        Predict what this video might be about and suggest a funny placeholder thumbnail category (ocean, forest, friends, cute, city). 
        Format your response in JSON: {"memo": "Suggested memo", "category": "프리다이빙|여행|우정릴스|인증샷|귀여움|캠핑팁", "thumbnailKeyword": "keyword"}`,
        config: {
           responseMimeType: "application/json"
        }
      });

      const result = JSON.parse(response.text);
      setMemo(prev => prev || result.memo);
      setCategory(result.category as Category);
      setThumbnail(`https://picsum.photos/seed/${result.thumbnailKeyword || 'video'}/400/600`);
    } catch (error) {
      console.error('Metadata extraction failed', error);
      // Fallback
      setThumbnail(`https://picsum.photos/seed/${Math.random()}/400/600`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!url) return alert('URL은 필수입니다.');

    const newBookmark: Bookmark = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      url,
      memo,
      category: category === '전체' ? '인증샷' : category,
      thumbnail: thumbnail || `https://picsum.photos/seed/${Math.random()}/400/600`
    };

    onSubmit(newBookmark);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-sm transition-all animate-in fade-in">
      <div className="bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[2rem] overflow-hidden shadow-2xl animate-in slide-in-from-bottom duration-300">
        <div className="px-6 pt-8 pb-4 flex items-center justify-between border-b border-slate-100">
          <h2 className="text-xl font-bold text-slate-800">새 북마크 추가</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
            <X className="h-5 w-5 text-slate-400" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-5">
          {/* URL Input */}
          <div className="space-y-1.5">
            <label className="text-xs font-bold text-slate-500 flex items-center gap-1.5 ml-1">
              <LinkIcon className="h-3 w-3" /> 영상 URL
            </label>
            <div className="relative">
              <input
                required
                type="url"
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                placeholder="https://www.instagram.com/reels/..."
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition-all"
              />
              <button
                type="button"
                onClick={handleAutoThumbnail}
                disabled={isProcessing}
                className="absolute right-2 top-1.5 bottom-1.5 px-3 bg-indigo-600 text-white rounded-xl text-xs font-bold hover:bg-indigo-700 disabled:bg-slate-300 flex items-center gap-1.5 transition-colors"
              >
                {isProcessing ? <Loader2 className="h-3 w-3 animate-spin" /> : <Sparkles className="h-3 w-3" />}
                {isProcessing ? '분석 중' : '자동 추출'}
              </button>
            </div>
          </div>

          {/* Memo Input */}
          <div className="space-y-1.5">
            <label className="text-xs font-bold text-slate-500 flex items-center gap-1.5 ml-1">
              <Type className="h-3 w-3" /> 메모
            </label>
            <textarea
              value={memo}
              onChange={(e) => setMemo(e.target.value)}
              placeholder="나만 알고 싶은 포인트나 기억할 점..."
              rows={2}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition-all resize-none"
            />
          </div>

          {/* Category Selector */}
          <div className="space-y-1.5">
            <label className="text-xs font-bold text-slate-500 flex items-center gap-1.5 ml-1">
              <Type className="h-3 w-3" /> 카테고리
            </label>
            <div className="grid grid-cols-3 gap-2">
              {CATEGORIES.filter(c => c !== '전체').map(cat => (
                <button
                  key={cat}
                  type="button"
                  onClick={() => setCategory(cat)}
                  className={`py-2 px-1 rounded-xl text-[10px] font-bold border transition-all
                    ${category === cat 
                      ? 'bg-indigo-50 border-indigo-200 text-indigo-600 ring-2 ring-indigo-500/20' 
                      : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'}`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          {/* Thumbnail Preview & Upload */}
          <div className="space-y-1.5">
            <label className="text-xs font-bold text-slate-500 flex items-center gap-1.5 ml-1">
              <Image className="h-3 w-3" /> 썸네일 설정
            </label>
            <div className="flex gap-4 items-center">
              <div className="w-20 aspect-[3/4] rounded-xl bg-slate-100 border-2 border-dashed border-slate-200 overflow-hidden flex items-center justify-center flex-shrink-0">
                {thumbnail ? (
                  <img src={thumbnail} className="w-full h-full object-cover" />
                ) : (
                  <Image className="h-6 w-6 text-slate-300" />
                )}
              </div>
              <div className="flex-grow">
                <label className="flex items-center justify-center gap-2 w-full py-3 bg-white border-2 border-slate-200 rounded-2xl text-xs font-bold text-slate-600 hover:bg-slate-50 cursor-pointer transition-all border-dashed">
                  <Upload className="h-4 w-4" />
                  이미지 직접 선택
                  <input type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
                </label>
                <p className="text-[10px] text-slate-400 mt-2 text-center">
                  이미지를 업로드하거나 '자동 추출'을 눌러보세요.
                </p>
              </div>
            </div>
          </div>

          {/* Buttons */}
          <div className="pt-2 flex gap-3">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-[1.25rem] font-bold text-sm hover:bg-slate-200 transition-colors"
            >
              취소
            </button>
            <button
              type="submit"
              className="flex-[2] py-4 bg-indigo-600 text-white rounded-[1.25rem] font-bold text-sm shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all"
            >
              저장하기
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddBookmarkForm;

/**
 * Short-Form Bookmark App Backend
 * To use: 
 * 1. Create a Google Spreadsheet.
 * 2. Extensions > Apps Script.
 * 3. Copy-paste this code.
 * 4. Deploy > New Deployment > Web App (Set "Who has access" to "Anyone").
 */

const SHEET_ID = 'YOUR_SPREADSHEET_ID'; // Leave empty to use active spreadsheet
const DRIVE_FOLDER_ID = 'YOUR_FOLDER_ID'; // Folder to save uploaded images

function doGet() {
  return HtmlService.createHtmlOutputFromFile('index')
    .setTitle('Shorts Favs')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1');
}

/**
 * Fetch all entries from Spreadsheet
 */
function getEntries() {
  const ss = SHEET_ID ? SpreadsheetApp.openById(SHEET_ID) : SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheets()[0];
  const data = sheet.getDataRange().getValues();

  if (data.length <= 1) return []; // Only header or empty

  const headers = data[0];
  return data.slice(1).map((row, idx) => {
    let obj = { id: (idx + 1).toString() };
    headers.forEach((header, colIdx) => {
      obj[header.toString().toLowerCase()] = row[colIdx];
    });
    return obj;
  });
}

/**
 * Add a new entry to Spreadsheet
 */
function addEntry(entry) {
  const ss = SHEET_ID ? SpreadsheetApp.openById(SHEET_ID) : SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheets()[0];

  // Columns: Date, URL, Thumbnail, Memo, Category
  sheet.appendRow([
    entry.date || new Date().toISOString(),
    entry.url,
    entry.thumbnail,
    entry.memo,
    entry.category
  ]);

  return { success: true };
}

/**
 * Upload Base64 image to Google Drive and return Web View URL
 */
function uploadImage(base64Data, fileName) {
  try {
    const folder = DRIVE_FOLDER_ID ? DriveApp.getFolderById(DRIVE_FOLDER_ID) : DriveApp.getRootFolder();
    const contentType = base64Data.split(',')[0].split(':')[1].split(';')[0];
    const bytes = Utilities.base64Decode(base64Data.split(',')[1]);
    const blob = Utilities.newBlob(bytes, contentType, fileName || 'upload_' + Date.now());

    const file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    return file.getDownloadUrl(); // Or file.getId() depending on preference
  } catch (e) {
    return "Error: " + e.toString();
  }
}

/**
 * Server-side OG Thumbnail extraction
 */
function getMetadata(videoUrl) {
  try {
    const response = UrlFetchApp.fetch(videoUrl);
    const html = response.getContentText();

    // Simple OG extraction regex
    const ogTitle = html.match(/<meta property="og:title" content="([^"]+)"/i)?.[1] || "";
    const ogImage = html.match(/<meta property="og:image" content="([^"]+)"/i)?.[1] || "";

    return {
      title: ogTitle,
      thumbnail: ogImage
    };
  } catch (e) {
    return null;
  }
}

