import { GAS_WEB_APP_URL } from './constants';
import { Bookmark, GASResponse } from './types';

export const gasApi = {
  /**
   * 모든 북마크 데이터 가져오기
   */
  async getEntries(): Promise<Bookmark[]> {
    const google = (window as any).google;
    if (typeof google !== 'undefined' && google.script && google.script.run) {
      return new Promise((resolve, reject) => {
        google.script.run
          .withSuccessHandler((data: Bookmark[]) => resolve(data))
          .withFailureHandler((err: any) => reject(err))
          .getEntries();
      });
    }

    if (!GAS_WEB_APP_URL) {
      return JSON.parse(localStorage.getItem('bookmarks') || '[]');
    }

    try {
      // GET 요청으로 데이터 가져오기
      const response = await fetch(`${GAS_WEB_APP_URL}?action=getEntries`);
      if (!response.ok) throw new Error('Network response was not ok');
      const result = await response.json();
      return result.data || [];
    } catch (error) {
      console.error('API Fetch Error:', error);
      // 실패 시 로컬 스토리지 데이터라도 반환
      return JSON.parse(localStorage.getItem('bookmarks') || '[]');
    }
  },

  /**
   * 새 북마크 추가
   */
  async addEntry(entry: Bookmark): Promise<GASResponse> {
    const google = (window as any).google;
    if (typeof google !== 'undefined' && google.script && google.script.run) {
      return new Promise((resolve, reject) => {
        google.script.run
          .withSuccessHandler((res: GASResponse) => resolve(res))
          .withFailureHandler((err: any) => reject(err))
          .addEntry(entry);
      });
    }

    if (!GAS_WEB_APP_URL) {
      const current = JSON.parse(localStorage.getItem('bookmarks') || '[]');
      localStorage.setItem('bookmarks', JSON.stringify([entry, ...current]));
      return { success: true };
    }

    try {
      /**
       * 핵심 수정: 
       * GAS POST 요청 시 application/json은 CORS 에러(OPTIONS 사전요청 미지원)를 발생시킵니다.
       * text/plain으로 보내면 'Simple Request'로 분류되어 사전요청 없이 전송 가능합니다.
       */
      await fetch(GAS_WEB_APP_URL, {
        method: 'POST',
        mode: 'no-cors', // 응답을 읽을 순 없지만 서버에 데이터는 전달됨
        headers: {
          'Content-Type': 'text/plain;charset=utf-8',
        },
        body: JSON.stringify({ action: 'addEntry', data: entry }),
      });

      // no-cors 모드에서는 응답 확인이 불가능하므로, 일단 성공으로 처리하고 
      // 로컬 스토리지를 업데이트하여 사용자에게 즉각적인 피드백을 줍니다.
      const current = JSON.parse(localStorage.getItem('bookmarks') || '[]');
      localStorage.setItem('bookmarks', JSON.stringify([entry, ...current]));

      return { success: true };
    } catch (error) {
      console.error('Save error:', error);
      return { success: false, message: String(error) };
    }
  }
};

