/**
 * 외부 POST 요청 처리
 */
function doPost(e) {
  try {
    let postData;

    // 요청 본문 파싱 (text/plain 대응)
    if (e.postData.contents) {
      postData = JSON.parse(e.postData.contents);
    } else {
      throw new Error("No post data contents found");
    }

    const action = postData.action;
    const data = postData.data;

    if (action === 'addEntry') {
      const result = addEntry(data);
      return ContentService.createTextOutput(JSON.stringify(result))
        .setMimeType(ContentService.MimeType.JSON);
    }

    return ContentService.createTextOutput(JSON.stringify({success: false, message: "Unknown action"}))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    // 로그 기록 (Apps Script 대시보드에서 확인 가능)
    console.error('Error in doPost: ' + err.toString());
    return ContentService.createTextOutput(JSON.stringify({success: false, message: err.toString()}))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function getEntries() {
  try {
    const ss = SHEET_ID ? SpreadsheetApp.openById(SHEET_ID) : SpreadsheetApp.getActiveSpreadsheet();
    const sheet = ss.getSheets()[0];
    const data = sheet.getDataRange().getValues();
    if (data.length <= 1) return [];

    const headers = data[0];
    return data.slice(1).map((row, idx) => {
      let obj = { id: (idx + 1).toString() };
      headers.forEach((header, colIdx) => {
        const key = header.toString().toLowerCase().trim();
        obj[key] = row[colIdx];
      });
      return obj;
    });
  } catch (e) {
    console.error('getEntries Error: ' + e.toString());
    return [];
  }
}

function addEntry(entry) {
  try {
    const ss = SHEET_ID ? SpreadsheetApp.openById(SHEET_ID) : SpreadsheetApp.getActiveSpreadsheet();
    const sheet = ss.getSheets()[0];

    // 시트가 비어있을 경우 헤더 추가
