      if (data[i][idColumnIndex].toString() === id.toString()) {
        sheet.deleteRow(i + 1);
        return { success: true };
      }
    }
    return { success: false, message: "ID not found" };
  } catch (e) {
    return { success: false, message: e.toString() };
  }
}

import { GAS_WEB_APP_URL } from './constants';
import { Bookmark, GASResponse } from './types';

export const gasApi = {
  async getEntries(): Promise<Bookmark[]> {
    if (!GAS_WEB_APP_URL) return JSON.parse(localStorage.getItem('bookmarks') || '[]');
    try {
      const response = await fetch(`${GAS_WEB_APP_URL}?action=getEntries`);
      const result = await response.json();
      return result.data || [];
    } catch (error) {
      return JSON.parse(localStorage.getItem('bookmarks') || '[]');
    }
  },

  async addEntry(entry: Bookmark): Promise<GASResponse> {
    return this.postToGas('addEntry', entry);
  },

  async updateEntry(entry: Bookmark): Promise<GASResponse> {
    return this.postToGas('updateEntry', entry);
  },

  async deleteEntry(id: string): Promise<GASResponse> {
    return this.postToGas('deleteEntry', { id });
  },

  async postToGas(action: string, data: any): Promise<GASResponse> {
    if (!GAS_WEB_APP_URL) {
      // 로컬 스토리지 모드 로직 (생략 가능하나 유지를 위해 남김)
      return { success: true };
    }
    try {
      await fetch(GAS_WEB_APP_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action, data }),
      });
      return { success: true };
    } catch (error) {
      return { success: false, message: String(error) };
    }
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { Plus, Search, PlayCircle, Loader2 } from 'lucide-react';
import { Bookmark, Category } from './types';
import Header from './components/Header';
import FilterBar from './components/FilterBar';
import BookmarkCard from './components/BookmarkCard';
import AddBookmarkForm from './components/AddBookmarkForm';
import { gasApi } from './api';

const App: React.FC = () => {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [filteredBookmarks, setFilteredBookmarks] = useState<Bookmark[]>([]);
  const [activeCategory, setActiveCategory] = useState<Category>('전체');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingBookmark, setEditingBookmark] = useState<Bookmark | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  const fetchBookmarks = useCallback(async () => {
    setIsLoading(true);
    try {
      const data = await gasApi.getEntries();
      setBookmarks(data);
    } catch (error) {
      console.error('Failed to fetch bookmarks:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchBookmarks();
  }, [fetchBookmarks]);

  useEffect(() => {
    let result = bookmarks;
    if (activeCategory !== '전체') {
      result = result.filter(b => b.category === activeCategory);
    }
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter(b => 
        b.memo.toLowerCase().includes(q) ||
        b.category.toLowerCase().includes(q)
      );
    }
    setFilteredBookmarks([...result].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  }, [bookmarks, activeCategory, searchQuery]);

  const handleSaveBookmark = async (bookmark: Bookmark) => {
    setIsLoading(true);
    if (editingBookmark) {
      // Update
      const result = await gasApi.updateEntry(bookmark);
      if (result.success) {
        setBookmarks(prev => prev.map(b => b.id === bookmark.id ? bookmark : b));
      }
    } else {
      // Add
      const result = await gasApi.addEntry(bookmark);
      if (result.success) {
        setBookmarks(prev => [bookmark, ...prev]);
      }
    }
    setIsFormOpen(false);
    setEditingBookmark(null);
    setIsLoading(false);
  };

  const handleDeleteBookmark = async (id: string) => {
    setIsLoading(true);
    const result = await gasApi.deleteEntry(id);
    if (result.success) {
      setBookmarks(prev => prev.filter(b => b.id !== id));
    }
    setIsLoading(false);
  };

  const handleEditClick = (bookmark: Bookmark) => {
    setEditingBookmark(bookmark);
    setIsFormOpen(true);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <Header />
      <main className="max-w-md mx-auto px-4 pt-4">
        <div className="relative mb-6">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-slate-400" />
          </div>
          <input
            type="text"
            className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-2xl bg-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all shadow-sm text-sm"
            placeholder="동영상 검색 또는 메모 검색..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        <FilterBar activeCategory={activeCategory} onCategoryChange={setActiveCategory} />

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 opacity-50">
            <Loader2 className="h-8 w-8 animate-spin text-indigo-600 mb-2" />
            <p className="text-sm font-medium">처리 중...</p>
          </div>
        ) : filteredBookmarks.length > 0 ? (
          <div className="grid grid-cols-2 gap-4 mt-6">
            {filteredBookmarks.map((bookmark) => (
              <BookmarkCard 
                key={bookmark.id} 
                bookmark={bookmark} 
                onDelete={handleDeleteBookmark}
                onEdit={handleEditClick}
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-20">
            <div className="bg-slate-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
              <PlayCircle className="h-8 w-8 text-slate-400" />
            </div>
            <p className="text-slate-500 text-sm">콘텐츠가 없습니다.</p>
          </div>
        )}
      </main>

      <button
        onClick={() => { setEditingBookmark(null); setIsFormOpen(true); }}
        className="fixed bottom-6 right-6 w-14 h-14 bg-indigo-600 text-white rounded-full shadow-lg flex items-center justify-center hover:bg-indigo-700 active:scale-95 transition-all z-40"
      >
        <Plus className="h-6 w-6" />
      </button>

      {isFormOpen && (
        <AddBookmarkForm 
          editingBookmark={editingBookmark}
          onClose={() => { setIsFormOpen(false); setEditingBookmark(null); }} 
          onSubmit={handleSaveBookmark}
        />
      )}
    </div>
  );
};

