  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    if (editingBookmark) {
      setUrl(editingBookmark.url);
      setMemo(editingBookmark.memo);
      setCategory(editingBookmark.category);
      setThumbnail(editingBookmark.thumbnail);
    }
